head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vMode = ""; // 신규,수정 구분
scwin.vBzProcsNo = ""; // 업무처리번호
scwin.procJob;
scwin.fn_GetPar, scwin.fn_SetPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // 부모창에서 클릭된 로우 코드
        const parentWin = $c.frame.path("../");
        scwin.vMode = parentWin.scwin.vMode;
        scwin.vBzProcsNo = parentWin.clickBzProcsNo;

        // 버튼 셋팅
        scwin.setButton();

        // 담당자구분 코드 셋팅
        await scwin.searchCode();

        // 오늘날짜 셋팅
        const vCurDate = $c.ut.cGetToday("yyyymmdd");
        edt_EDU_DD.setValue(vCurDate);

        // 첨부파일 조회
        await scwin.fileSync();
        if (scwin.vMode === "U") {
            // 교육이수현황 조회
            await scwin.listSync();

            // 성명셋팅
            await scwin.setChrgNM();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF71005_P.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF71005_P.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name btn_save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_save_onclick = async function() {
    try {
        await scwin.save();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF71005_P.btn_save_onclick" });
    }
};

/**
 * @method
 * @name btn_modify_onclick
 * @description 「수정」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_modify_onclick = async function() {
    try {
        await scwin.modify();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF71005_P.btn_modify_onclick" });
    }
};

/**
 * @method
 * @name btn_delete_onclick
 * @description 「삭제」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_delete_onclick = function() {
    try {
        scwin.delete();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF71005_P.btn_delete_onclick" });
    }
};

/**
 * @method
 * @name cmb_CHRG_TP_CD_onselchange
 * @description cmb_CHRG_TP_CD onselchange 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cmb_CHRG_TP_CD_onselchange = async function() {
    try {
        await scwin.setChrgNM();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF71005_P.cmb_CHRG_TP_CD_onselchange" });
    }
};

/**
 * @method
 * @name btn_FileDelete_onclick
 * @description 「파일삭제」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_FileDelete_onclick = function() {
    try {
        dts_fileList.removeRow(dts_fileList.getRowPosition());
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF71005_P.btn_FileDelete_onclick" });
    }
};

/**
 * @method
 * @name grd_fielList_OnDblClick
 * @description grd_fielList 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_fielList_OnDblClick = function(row, colid) {
    try {
        // 파일다운로드
        if (row === 0) return;
        if (dts_fileList.getRowStatus(dts_fileList.getRowPosition()) === 0) {
            $c.dn.fn_filedown(scwin.vBzProcsNo, dts_fileList.getCellData(row, "ATTACH_SEQ"));
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF71005_P.grd_fielList_OnDblClick" });
    }
};

/**
 * @method
 * @name btn_file_onclick
 * @description 「파일추가」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_file_onclick = async function() {
    try {
        if (dts_fileList.getRowCount() === 10) {
            await $c.win.alert("첨부파일은 최대 10개 입니다.");
            return;
        }
        dts_fileList.insertRow();
        inf_find.open();
        if (inf_find.getValue() !== "") {
            // 확장자 확인
            if (!$c.lcd.checkBadExt(inf_find.getValue())) {
                await $c.win.alert("해당파일은 첨부할 수 없습니다.");
                dts_fileList.removeRow(dts_fileList.getRowPosition());
                inf_find.setValue("");
                return;
            }
            dts_fileList.setCellData(dts_fileList.getRowPosition(), "ATTACH_FILE_NM", inf_find.getValue());
            dts_fileList.setCellData(dts_fileList.getRowPosition(), "ATTACH_SEQ", dts_fileList.getRowPosition());
            dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileUrl", inf_find.getValue());
        } else {
            dts_fileList.removeRow(dts_fileList.getRowPosition());
        }
        if (!scwin.canUploadFile()) {
            await $c.win.alert('30MB 이하의 파일만 첨부 가능합니다.');
            dts_fileList.removeRow(dts_fileList.getRowPosition());
            return;
        }
        inf_find.setValue("");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF71005_P.btn_file_onclick" });
    }
};

/**
 * @method
 * @name img_IsuSearch_onclick
 * @description img_IsuSearch 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_IsuSearch_onclick = function() {
    try {
        scwin.fn_SetPar = scwin.setParIsur2;
        scwin.fn_GetPar = scwin.getParIsur2;
        $c.lcd.fn_PopFindDigitalIsurAppl();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF71005_P.img_IsuSearch_onclick" });
    }
};

/**
 * @method
 * @name img_EDU_DD_onclick
 * @description img_EDU_DD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_EDU_DD_onclick = function() {
    try {
        popUpCalendar2(edt_EDU_DD);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF71005_P.img_EDU_DD_onclick" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", scwin.procJob));
        await $c.win.alert(trs_Save);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF71005_P.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-0001", scwin.procJob));
        scwin.parentRefresh();
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF71005_P.trs_Save_OnSuccess" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name searchCode
 * @description 공통코드 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchCode = async function() {
    const sbmOptions = {
        id : "sbm_dts_CHRG_TP_CD",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_CHRG_TP_CD=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    let strCbd = "",
        j;
    for (j = 1; j <= dts_CHRG_TP_CD.getRowCount(); j++) {
        const val = dts_CHRG_TP_CD.getCellData(j, "VALUE");
        if (val.charAt(0) === "D") {
            strCbd = strCbd + (strCbd === "" ? "" : ",") + val + "^" + dts_CHRG_TP_CD.getCellData(j, "TEXT");
        }
    }
    cmb_CHRG_TP_CD.CBData = strCbd;

    // 인덱스 첫번째로
    cmb_CHRG_TP_CD.setSelectedIndex(0);
    await scwin.setChrgNM();
};

/**
 * @method
 * @name setChrgNM
 * @description 담당자 리스트 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setChrgNM = async function() {
    // 담당자 리스트 조회
    url += "?method=corpDisclsChrgList&inputMessageId=DIGITAL_SUPPORT_EDU_SEARCH_OUT";
    url += "&CHRG_TP_CD=" + cmb_CHRG_TP_CD.getValue();
    url += "&ISUR_CD=" + txb_ISUR_CD.getValue();
    const sbmOptions = {
        id : "sbm_dts_CHRG_NM",
        action : "/digital/DigitalSupport.do",
        ref : "",
        target : "dts_CHRG_NM=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const charNm = dts_Item.getCellData(1, "CHRG_NM");
    let strCbd = "",
        j;
    for (j = 1; j <= dts_CHRG_NM.getRowCount(); j++) {
        strCbd = strCbd + (strCbd === "" ? "" : ",") + dts_CHRG_NM.getCellData(j, "CHRG_NM") + "^" + dts_CHRG_NM.getCellData(j, "CHRG_NM");
    }
    if (strCbd) {
        cmb_CHRG_NM.CBData = strCbd;
    } else {
        cmb_CHRG_NM.CBData = "^ ";
    }

    // 인덱스 셋팅
    if (charNm) cmb_CHRG_NM.BindColVal = charNm;

    else cmb_CHRG_NM.setSelectedIndex(0);
};

/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    url += "?SCREN_ID=" + "ULDSTF71005_P.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=digitalEduCompltList&inputMessageId=DIGITAL_SUPPORT_EDU_SEARCH_OUT";
    url += "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    url += "&ISUR_CD=";
    url += "&CHRG_NM=";
    const sbmOptions = {
        id : "sbm_dts_Item",
        action : "/digital/DigitalSupport.do",
        ref : "",
        target : "dts_Item=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name fileSync
 * @description file Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fileSync = async function() {
    let url = "";
    url += "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    const sbmOptions = {
        id : "sbm_dts_fileList",
        action : "/digital/DigitalListedRcv.do",
        ref : "",
        target : "dts_fileList=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setButton
 * @description set Button 처리
 * @returns {void}
 * @hidden N
 */
scwin.setButton = function() {
    if (scwin.vMode === "I") {
        // 저장일 경우
        // 저장 -> 활성화
        btn_save.setBackgroundImage("../img/btn_save.gif");
        btn_save.setDisabled(false);

        // 수정 -> 비활성화
        btn_modify.setBackgroundImage("../img/btn_modify_d.gif");
        btn_modify.setDisabled(true);

        // 삭제 -> 비활성화
        btn_delete.setBackgroundImage("../img/btn_delete_d.gif");
        btn_delete.setDisabled(true);
    } else if (scwin.vMode === "U") {
        // 수정일경우
        // 저장 -> 비활성화
        btn_save.setBackgroundImage("../img/btn_save_d.gif");
        btn_save.setDisabled(true);

        // 수정 -> 활성화
        btn_modify.setBackgroundImage("../img/btn_modify.gif");
        btn_modify.setDisabled(false);

        // 삭제 -> 활성화
        btn_delete.setBackgroundImage("../img/btn_delete.gif");
        btn_delete.setDisabled(false);
    }
};

/**
 * @method
 * @name save
 * @description 저장버튼 클릭
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    if (await scwin.validation()) {
        if (!$c.lcd.fn_isProcess(scwin.vMode)) return;

        // 데이터 셋팅
        scwin.vBzProcsNo = await $c.stf.getNewBzProcNo(dts_BzProcsNo); // 업무처리번호 새로 지정
        const ISUR_CD = txb_ISUR_CD.getValue();
        const CHRG_TP_CD = cmb_CHRG_TP_CD.getValue();
        const CHRG_NM = cmb_CHRG_NM.getValue();
        const EDU_DD = edt_EDU_DD.getValue();
        const REMK = txa_REMK.getValue();
        let vHeadString = "LIST_APPLNT_ISUR_CD:STRING(5),";
        vHeadString += "CHRG_TP_CD:STRING(2),";
        vHeadString += "CHRG_NM:STRING(80),";
        vHeadString += "EDU_DD:STRING(8),";
        vHeadString += "REMK:STRING(2000)";
        // dts_Item.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
        dts_Item.insertRow();
        dts_Item.setCellData(1, "LIST_APPLNT_ISUR_CD", ISUR_CD);
        dts_Item.setCellData(1, "CHRG_TP_CD", CHRG_TP_CD);
        dts_Item.setCellData(1, "CHRG_NM", CHRG_NM);
        dts_Item.setCellData(1, "EDU_DD", EDU_DD);
        dts_Item.setCellData(1, "REMK", REMK);
        scwin.procJob = "저장";
        scwin.trs(TR_JOB_INSERT);
    }
};

/**
 * @method
 * @name modify
 * @description 수정버튼 클릭
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.modify = async function() {
    if (await scwin.validation()) {
        if (!$c.lcd.fn_isProcess(scwin.vMode)) return;
        scwin.procJob = "수정";
        scwin.trs(TR_JOB_UPDATE);
    }
};

/**
 * @method
 * @name delete
 * @description 삭제버튼 클릭
 * @returns {void}
 * @hidden N
 */
scwin.delete = function() {
    scwin.vMode = "D";
    if (!$c.lcd.fn_isProcess("D")) return;
    scwin.trs(TR_JOB_DELETE);
};

/**
 * @method
 * @name validation
 * @description validation 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.validation = async function() {
    // 상장신청인(명)
    if (txb_ISUR_CD.getValue() === "") {
        await $c.win.alert("상장신청인(명)은 필수입니다.");
        return false;
    }

    // 담당자구분
    if (cmb_CHRG_TP_CD.getValue() === "") {
        await $c.win.alert("담당자 구분값은 필수입니다.");
        return false;
    }

    // 성명
    if (cmb_CHRG_NM.getValue() === "") {
        await $c.win.alert("담당자 성명은 필수입니다.");
        return false;
    }

    // 교육일자
    if (edt_EDU_DD.getValue() === "") {
        await $c.win.alert("교육일자는 필수입니다.");
        return false;
    }

    // 비고
    if (txa_REMK.getValue() === "") {
        await $c.win.alert("비고란 입력은 필수입니다.");
        return false;
    }
    if (!$c.stf.checkMaxLength(txa_REMK, 2000, "비고")) return false;
    return true;
};

/**
 * @method
 * @name trs
 * @description 저장 및 수정 시 트랜잭션 정보 설정
 * @param {*} trsIdx trsIdx
 * @returns {void}
 * @hidden N
 */
scwin.trs = function(trsIdx) {
    if (scwin.vMode === 'I') {
        vScrenTpCD = SCREN_PROCS_TP_CD_02;
    } else if (scwin.vMode === 'U') {
        vScrenTpCD = SCREN_PROCS_TP_CD_03;
    } else if (scwin.vMode === 'D') {
        vScrenTpCD = SCREN_PROCS_TP_CD_04;
    }
    if (scwin.vMode === "I" || scwin.vMode === "U") {
        // 교육이수현황 추가/수정
        trs_Save.Action = $c.lcd.fn_encodeNSession("/digital/DigitalSupport.do?method=saveEduCompltStat&SCREN_ID=" + "ULDSTF71005_P.xml" + "&SCREN_PROCES_TP_CD=" + vScrenTpCD);
    } else {
        // 교육이수현황 삭제
        trs_Save.Action = $c.lcd.fn_encodeNSession("/digital/DigitalSupport.do?method=deleteEduCompltStat&SCREN_ID=" + "ULDSTF71005_P.xml" + "&SCREN_PROCES_TP_CD=" + vScrenTpCD);
    }
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_Item, I:pFile=dts_fileList)";
    trs_Save.Parameters = "TRS_IDX=" + trsIdx + ",BZ_PROCS_NO=" + scwin.vBzProcsNo;
    trs_Save.Post();
};

/**
 * @method
 * @name canUploadFile
 * @description can Upload File 처리
 * @returns {void}
 * @hidden N
 */
scwin.canUploadFile = function() {
    const maxFileSize = 1024 * 1024 * 30; // 30MB
    const mySize = inf_find.FileInfo('size');
    if (mySize < maxFileSize) {
        return true;
    } else {
        return false;
    }
};

/**
 * @method
 * @name filedown
 * @description 파일 다운로드 (gubun = 311) (Params : bzProcsNo:업무처리번호 , attachFileNo: 번호)
 * @param {*} bzProcsNo bzProcsNo
 * @param {*} attachSeq attachSeq
 * @returns {void}
 * @hidden N
 */
scwin.filedown = function(bzProcsNo, attachSeq) {
    location.href = "/filedownload.do?SCREN_ID=" + "ULDSTF71005_P.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_08 + "&BZ_PROCS_NO=" + bzProcsNo + "&ATTACH_SEQ=" + attachSeq + "&gubun=311";
};

/**
 * @method
 * @name setParIsur2
 * @description 상장신청인 선택 팝업호출용
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setParIsur2 = async function(arrPar) {
    const dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn === "Y") {
        txb_ISUR_CD.setValue(arrPar[0].ISUR_CD);
        txb_ISUR_NM.setValue(arrPar[0].ISUR_NM);
    }

    // 성명셋팅
    await scwin.setChrgNM();
};

/**
 * @method
 * @name getParIsur2
 * @description get Par Isur2 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsur2 = function(arrPar) {
    arrPar[0] = "lds.stf.digital.select.isuracptlist.condition";
    return arrPar.length;
};

/**
 * @method
 * @name parentRefresh
 * @description 교육이수현황  리스트 재조회
 * @returns {void}
 * @hidden N
 */
scwin.parentRefresh = function() {
    const fr_fn_list_sync = $c.frame.path("../").fn_list_sync;
    fr_fn_list_sync();
};
